import numpy as np
from scipy.optimize import minimize

def objective_function(x): return -np.sum(x[64:])
def constraints(x):
    n=32; centers=x[:64].reshape((n,2)); radii=x[64:]
    b_con=np.concatenate([centers[:,0]-radii, 1-centers[:,0]-radii, centers[:,1]-radii, 1-centers[:,1]-radii])
    diff=centers[:,np.newaxis,:]-centers[np.newaxis,:,:]; dist_sq=np.sum(diff**2,axis=-1)
    indices=np.triu_indices(n,k=1); rad_sum_sq=(radii[indices[0]]+radii[indices[1]])**2
    o_con=dist_sq[indices]-rad_sum_sq; return np.concatenate([b_con,o_con])

def get_seed(seed_val): # PURE FPS
    rng=np.random.default_rng(seed_val)
    points=[rng.uniform(0.1,0.9,2)]
    for _ in range(31):
        candidates=rng.uniform(0.1,0.9,(200,2)); dists=np.sum((candidates[:,np.newaxis,:]-np.array(points)[np.newaxis,:,:])**2,axis=-1)
        points.append(candidates[np.argmax(np.min(dists,axis=1))])
    return np.array(points)

def iterative_finalize(centers, radii):
    n=32; final_radii=np.copy(radii); R_MIN=1e-8; epsilon=1e-9
    for _ in range(10):
        violations = 0
        for i in range(n):
            x_i, y_i = centers[i]; new_r = min(final_radii[i], x_i, 1-x_i, y_i, 1-y_i)
            if new_r < final_radii[i]: final_radii[i] = new_r; violations += 1
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.linalg.norm(centers[i] - centers[j])
                rad_sum = final_radii[i] + final_radii[j]
                if rad_sum >= dist - epsilon:
                    overlap = rad_sum - (dist - epsilon); reduction = overlap / 2.0
                    r_i_new = max(R_MIN, final_radii[i]-reduction); r_j_new = max(R_MIN, final_radii[j]-reduction)
                    if r_i_new < final_radii[i] or r_j_new < final_radii[j]:
                        final_radii[i]=r_i_new; final_radii[j]=r_j_new; violations += 1
        if violations == 0: break
    return final_radii

def construct_packing() -> tuple:
    n=32; num_starts=8; best_score=-np.inf; best_solution=None
    for i in range(num_starts):
        initial_centers=get_seed(i)
        x0=np.concatenate([initial_centers.flatten(),np.full(n,0.05)])
        bounds=[(0,1)]*(2*n)+[(0,0.5)]*n
        cons=[{'type':'ineq','fun':constraints}]
        result=minimize(objective_function,x0,method='SLSQP',bounds=bounds,constraints=cons,options={'maxiter':200,'ftol':1e-7})
        if result.success and -result.fun>best_score:
            best_score=-result.fun; best_solution=result.x
    if best_solution is None: return np.random.rand(n,2),np.full(n,0.01)

    final_centers=best_solution[:64].reshape((n,2))
    slsqp_radii=best_solution[64:]

    # Use the robust finalizer
    final_radii = iterative_finalize(final_centers, slsqp_radii)

    return final_centers,final_radii
